Message: {{ $json.Message }}

parameters.jsCode:
const FALLBACK_SCORE = 1;
const FALLBACK_REASON = 'The AI response could not be parsed, so a default low score was assigned.';

// Retrieve original form data from the Form Trigger node
let formData = {};
try {
  formData = $('Form Trigger').first().json || {};
} catch (e) {
  formData = {};
}

const name = formData.Name !== undefined && formData.Name !== null ? String(formData.Name) : '';
const budget = formData.Budget !== undefined && formData.Budget !== null ? String(formData.Budget) : '';
const message = formData.Message !== undefined && formData.Message !== null ? String(formData.Message) : '';

// Read AI output from the Basic LLM Chain
const item = $input.first();
let raw = '';
if (item && item.json) {
  raw = item.json.text !== undefined ? item.json.text : (item.json.output !== undefined ? item.json.output : (item.json.response !== undefined ? item.json.response : ''));
}

let score = FALLBACK_SCORE;
let reason = FALLBACK_REASON;

try {
  let parsed;
  if (raw && typeof raw === 'object') {
    parsed = raw;
  } else {
    let cleaned = String(raw || '').trim();
    // Remove markdown code fences if present
    cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    try {
      parsed = JSON.parse(cleaned);
    } catch (innerErr) {
      // Try extracting the first JSON object from the text
      const match = cleaned.match(/\{[\s\S]*\}/);
      if (!match) {
        throw innerErr;
      }
      parsed = JSON.parse(match[0]);
    }
  }

  const num = Number(parsed.score);
  if (Number.isFinite(num)) {
    score = Math.min(10, Math.max(1, Math.round(num)));
    reason = typeof parsed.reason === 'string' && parsed.reason.trim() !== ''
      ? parsed.reason.trim()
      : 'No reason was provided by the AI.';
  } else {
    score = FALLBACK_SCORE;
    reason = 'The AI returned an invalid score, so a default low score was assigned.';
  }
} catch (err) {
  score = FALLBACK_SCORE;
  reason = FALLBACK_REASON;
}

return [
  {
    json: {
      score,
      reason,
      name,
      budget,
      message
    }
  }
];
